package com.tourstravels.controller;

import com.tourstravels.model.*;
import com.tourstravels.repository.*;
import com.tourstravels.service.EmailService;
import com.tourstravels.service.PlanPdfService;
import com.tourstravels.service.RegistrationService;
import jakarta.validation.Valid;
import java.io.IOException;
import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.Principal;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.LocalTime;
import org.springframework.core.io.ByteArrayResource;
import org.springframework.data.domain.Sort;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;

@Controller
public class WebController {
 private final DestinationRepository destinations; private final TourPackageRepository packages; private final HotelRepository hotels; private final UserRepository users; private final BookingRepository bookings; private final ReviewRepository reviews; private final ContactMessageRepository messages; private final RegistrationService registration; private final EmailService emailService; private final PlanPdfService planPdfService;
 public WebController(DestinationRepository d,TourPackageRepository p,HotelRepository h,UserRepository u,BookingRepository b,ReviewRepository r,ContactMessageRepository m,RegistrationService rs,EmailService emailService,PlanPdfService planPdfService){destinations=d;packages=p;hotels=h;users=u;bookings=b;reviews=r;messages=m;registration=rs;this.emailService=emailService;this.planPdfService=planPdfService;}
 @ModelAttribute("currentUser") public AppUser currentUser(Principal principal){return principal==null?null:users.findByEmail(principal.getName()).orElse(null);}
 @GetMapping("/") public String home(Model m){m.addAttribute("destinations",destinations.findByFeaturedTrueAndActiveTrue());m.addAttribute("packages",packages.findByFeaturedTrueAndActiveTrue());m.addAttribute("hotels",hotels.findByActiveTrueOrderByRatingDesc().stream().limit(3).toList());m.addAttribute("reviews",reviews.findByApprovedTrueOrderByCreatedAtDesc().stream().limit(3).toList());return "index";}
 @GetMapping("/destinations") public String destinationList(@RequestParam(required=false) String q,Model m){m.addAttribute("destinations",q==null||q.isBlank()?destinations.findByActiveTrueOrderByNameAsc():destinations.findByNameContainingIgnoreCaseOrCountryContainingIgnoreCase(q,q));m.addAttribute("q",q==null?"":q);return "destinations";}
 @GetMapping("/destinations/{id}") public String destinationDetail(@PathVariable Long id,Model m){var d=destinations.findById(id).orElseThrow();m.addAttribute("destination",d);m.addAttribute("packages",packages.findByActiveTrueOrderByFeaturedDesc().stream().filter(p->p.getDestination()!=null&&p.getDestination().getId().equals(id)).toList());return "destination-detail";}
 @GetMapping("/packages") public String packageList(@RequestParam(required=false) String q,@RequestParam(required=false) String category,Model m){var list=packages.findByActiveTrueOrderByFeaturedDesc();if(q!=null&&!q.isBlank())list=list.stream().filter(p->p.getTitle().toLowerCase().contains(q.toLowerCase())||(p.getDestination()!=null&&p.getDestination().getName().toLowerCase().contains(q.toLowerCase()))).toList();if(category!=null&&!category.isBlank())list=list.stream().filter(p->category.equalsIgnoreCase(p.getCategory())).toList();m.addAttribute("packages",list);m.addAttribute("q",q==null?"":q);m.addAttribute("category",category==null?"":category);return "packages";}
 @GetMapping("/packages/{id}") public String packageDetail(@PathVariable Long id,Model m){m.addAttribute("tourPackage",packages.findById(id).orElseThrow());return "package-detail";}
 @GetMapping("/hotels") public String hotelList(Model m){m.addAttribute("hotels",hotels.findByActiveTrueOrderByRatingDesc());return "hotels";}
 @GetMapping("/activities") public String activities(){return "activities";}
 @GetMapping("/contact") public String contact(Model m){m.addAttribute("contactMessage",new ContactMessage());return "contact";}
 @PostMapping("/contact") public String sendContact(@Valid @ModelAttribute ContactMessage contactMessage,BindingResult result,RedirectAttributes ra){if(result.hasErrors()){ra.addFlashAttribute("error","Please check the form and enter valid details.");return "redirect:/contact";}messages.save(contactMessage);ra.addFlashAttribute("success","Thanks for contacting us! Our team will get back to you soon.");return "redirect:/contact";}
 @GetMapping("/login") public String login(){return "login";}
 @GetMapping("/register") public String registerPage(Model m){m.addAttribute("registration",new RegistrationForm());return "register";}
 @PostMapping("/register") public String register(@RequestParam String fullName,@RequestParam String email,@RequestParam String password,@RequestParam String confirmPassword,RedirectAttributes ra){if(password.length()<8){ra.addFlashAttribute("error","Password must be at least 8 characters.");return "redirect:/register";}if(!password.equals(confirmPassword)){ra.addFlashAttribute("error","Passwords do not match.");return "redirect:/register";}try{registration.register(fullName,email,password);}catch(IllegalArgumentException ex){ra.addFlashAttribute("error",ex.getMessage());return "redirect:/register";}ra.addFlashAttribute("success","Account created. Please log in.");return "redirect:/login";}
 @GetMapping("/account") public String account(Principal p,Model m){AppUser u=users.findByEmail(p.getName()).orElseThrow();m.addAttribute("bookings",bookings.findByUserIdOrderByCreatedAtDesc(u.getId()));return "account";}
 @PostMapping("/bookings/create") public String createBooking(@RequestParam(required=false) Long packageId,@RequestParam(required=false) Long hotelId,@RequestParam String startDate,@RequestParam(required=false) String endDate,@RequestParam(defaultValue="2") int travelers,@RequestParam(required=false) String specialRequests,Principal p,RedirectAttributes ra){if(travelers<1||travelers>20){ra.addFlashAttribute("error","Travelers must be between 1 and 20.");return "redirect:/packages";}Booking b=new Booking();b.setUser(users.findByEmail(p.getName()).orElseThrow());if(packageId!=null){TourPackage tp=packages.findById(packageId).orElseThrow();b.setTourPackage(tp);b.setTotalAmount(tp.getPrice().multiply(BigDecimal.valueOf(travelers)));b.setAmountDue(tp.getPrice().multiply(BigDecimal.valueOf(travelers)));}
 else if(hotelId!=null){Hotel h=hotels.findById(hotelId).orElseThrow();b.setHotel(h);b.setTotalAmount(h.getPricePerNight());b.setAmountDue(h.getPricePerNight());}
 else{return "redirect:/packages";}LocalDate start=LocalDate.parse(startDate);b.setStartDate(start);b.setEndDate(endDate==null||endDate.isBlank()?start.plusDays(b.getTourPackage()!=null?b.getTourPackage().getDurationDays():1):LocalDate.parse(endDate));b.setTravelers(travelers);b.setSpecialRequests(specialRequests);b.setStatus(BookingStatus.PENDING);bookings.save(b);ra.addFlashAttribute("success","Booking request submitted! Our admin team will prepare your travel plan.");return "redirect:/account";}
 @PostMapping("/bookings/{id}/cancel") public String cancelBooking(@PathVariable Long id,Principal p,RedirectAttributes ra){Booking b=bookings.findById(id).orElseThrow();if(!b.getUser().getEmail().equals(p.getName()))throw new org.springframework.security.access.AccessDeniedException("Not your booking");if(b.getStatus()==BookingStatus.PENDING||b.getStatus()==BookingStatus.APPROVED||b.getStatus()==BookingStatus.PAID||b.getStatus()==BookingStatus.CONFIRMED){b.setStatus(BookingStatus.CANCELLED);bookings.save(b);ra.addFlashAttribute("success","Booking cancelled.");}return "redirect:/account";}
 @PostMapping("/bookings/{id}/pay") public String payBooking(@PathVariable Long id,@RequestParam(required=false) String paymentReference,Principal p,RedirectAttributes ra){Booking b=bookings.findById(id).orElseThrow();if(!b.getUser().getEmail().equals(p.getName()))throw new org.springframework.security.access.AccessDeniedException("Not your booking");if(b.getStatus()==BookingStatus.APPROVED||b.getStatus()==BookingStatus.PAID){b.setStatus(BookingStatus.PAID);b.setPaymentReference(paymentReference==null||paymentReference.isBlank()?"PAY-"+System.currentTimeMillis():paymentReference);b.setPaymentReceivedAt(LocalDateTime.now());bookings.save(b);ra.addFlashAttribute("success","Payment received. Admin will confirm your trip soon.");}else{ra.addFlashAttribute("error","This booking is not ready for payment yet.");}return "redirect:/account";}
 @GetMapping("/bookings/{id}/plan/download") public ResponseEntity<ByteArrayResource> downloadPlan(@PathVariable Long id,Principal p){Booking b=bookings.findById(id).orElseThrow();if(p!=null&&!b.getUser().getEmail().equals(p.getName())&&!p.getName().equals("admin@tours.com")){throw new org.springframework.security.access.AccessDeniedException("Not your booking");}Path pdfPath=b.getPlanPdfPath()==null||b.getPlanPdfPath().isBlank()?null:Path.of(b.getPlanPdfPath());if(pdfPath==null||!Files.exists(pdfPath)){try{b.setPlanPdfPath(planPdfService.createPlanPdf(b));bookings.save(b);pdfPath=Path.of(b.getPlanPdfPath());}catch(IOException e){throw new IllegalStateException("Could not create travel plan PDF.",e);}}byte[] bytes;try{bytes=Files.readAllBytes(pdfPath);}catch(IOException e){throw new IllegalStateException("Could not read travel plan PDF.",e);}return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=travel-plan-"+b.getId()+".pdf").contentType(MediaType.APPLICATION_PDF).body(new ByteArrayResource(bytes));}
 @PostMapping("/reviews") public String review(@RequestParam Long packageId,@RequestParam int rating,@RequestParam String comment,Principal p,RedirectAttributes ra){if(rating<1||rating>5){ra.addFlashAttribute("error","Rating must be between 1 and 5.");return "redirect:/account";}Review r=new Review();r.setUser(users.findByEmail(p.getName()).orElseThrow());r.setTourPackage(packages.findById(packageId).orElseThrow());r.setRating(rating);r.setComment(comment);reviews.save(r);ra.addFlashAttribute("success","Thanks for sharing your review!");return "redirect:/account";}
 @GetMapping("/access-denied") public String denied(){return "access-denied";}
 @GetMapping("/admin") @PreAuthorize("hasRole('ADMIN')") public String admin(Model m){m.addAttribute("destinationCount",destinations.count());m.addAttribute("packageCount",packages.count());m.addAttribute("hotelCount",hotels.count());m.addAttribute("customerCount",users.count());m.addAttribute("pendingCount",bookings.countByStatus(BookingStatus.PENDING));m.addAttribute("bookings",bookings.findAll(Sort.by(Sort.Direction.DESC,"createdAt")).stream().limit(8).toList());m.addAttribute("pendingBookings",bookings.findByStatusOrderByCreatedAtDesc(BookingStatus.PENDING).stream().limit(5).toList());m.addAttribute("messageCount",messages.countByHandledFalse());return "admin/dashboard";}
 @GetMapping("/admin/requests") @PreAuthorize("hasRole('ADMIN')") public String adminRequests(Model m){m.addAttribute("bookings",bookings.findAll(Sort.by(Sort.Direction.DESC,"createdAt")));return "admin/requests";}
 @GetMapping("/admin/bookings/{id}/plan") @PreAuthorize("hasRole('ADMIN')") public String adminPlanForm(@PathVariable Long id,Model m){Booking b=bookings.findById(id).orElseThrow();m.addAttribute("booking",b);return "admin/booking-plan-form";}
 @PostMapping("/admin/bookings/{id}/plan") @PreAuthorize("hasRole('ADMIN')") public String savePlan(@PathVariable Long id,@RequestParam(required=false) String travelDate,@RequestParam(required=false) String travelTime,@RequestParam(required=false) String pickupLocation,@RequestParam(required=false) String travelPlaces,@RequestParam(required=false) String travelPlan,@RequestParam(required=false, defaultValue="0") BigDecimal amountDue,@RequestParam(required=false) String adminNotes,RedirectAttributes ra){Booking b=bookings.findById(id).orElseThrow();if(travelDate!=null&&!travelDate.isBlank())b.setTravelDate(LocalDate.parse(travelDate));if(travelTime!=null&&!travelTime.isBlank())b.setTravelTime(LocalTime.parse(travelTime));b.setPickupLocation(pickupLocation);b.setTravelPlaces(travelPlaces);b.setTravelPlan(travelPlan);b.setAdminNotes(adminNotes);b.setAmountDue(amountDue==null?BigDecimal.ZERO:amountDue);b.setStatus(BookingStatus.APPROVED);try{b.setPlanPdfPath(planPdfService.createPlanPdf(b));}catch(IOException e){throw new IllegalStateException("Unable to generate travel plan PDF.",e);}b.setPlanSent(false);bookings.save(b);emailService.sendPlanEmail(b);ra.addFlashAttribute("success","Travel plan sent to the user and PDF attached in email.");return "redirect:/admin/requests";}
 @PostMapping("/admin/bookings/{id}/confirm") @PreAuthorize("hasRole('ADMIN')") public String confirmBooking(@PathVariable Long id,RedirectAttributes ra){Booking b=bookings.findById(id).orElseThrow();if(b.getStatus()!=BookingStatus.PAID){ra.addFlashAttribute("error","Only paid bookings can be confirmed.");return "redirect:/admin/requests";}b.setStatus(BookingStatus.CONFIRMED);bookings.save(b);emailService.sendConfirmationEmail(b);ra.addFlashAttribute("success","Booking confirmed and user notified by email.");return "redirect:/admin/requests";}
 @GetMapping("/admin/destinations") @PreAuthorize("hasRole('ADMIN')") public String adminDestinations(Model m){m.addAttribute("destinations",destinations.findAll());return "admin/destinations";}
 @GetMapping("/admin/destinations/new") @PreAuthorize("hasRole('ADMIN')") public String newDestination(Model m){m.addAttribute("destination",new Destination());return "admin/destination-form";}
 @PostMapping("/admin/destinations/save") @PreAuthorize("hasRole('ADMIN')") public String saveDestination(@Valid @ModelAttribute Destination destination,BindingResult result,RedirectAttributes ra){if(result.hasErrors())return "admin/destination-form";destinations.save(destination);ra.addFlashAttribute("success","Destination saved.");return "redirect:/admin/destinations";}
 @PostMapping("/admin/destinations/{id}/delete") @PreAuthorize("hasRole('ADMIN')") public String deleteDestination(@PathVariable Long id,RedirectAttributes ra){destinations.deleteById(id);ra.addFlashAttribute("success","Destination deleted.");return "redirect:/admin/destinations";}
 @GetMapping("/admin/packages") @PreAuthorize("hasRole('ADMIN')") public String adminPackages(Model m){m.addAttribute("packages",packages.findAll());return "admin/packages";}
 @GetMapping("/admin/packages/new") @PreAuthorize("hasRole('ADMIN')") public String newPackage(Model m){m.addAttribute("tourPackage",new TourPackage());m.addAttribute("destinations",destinations.findAll());return "admin/package-form";}
 @PostMapping("/admin/packages/save") @PreAuthorize("hasRole('ADMIN')") public String savePackage(@Valid @ModelAttribute TourPackage tourPackage,BindingResult result,@RequestParam(required=false) Long destinationId,Model m,RedirectAttributes ra){if(result.hasErrors()){m.addAttribute("destinations",destinations.findAll());return "admin/package-form";}if(destinationId!=null)tourPackage.setDestination(destinations.findById(destinationId).orElse(null));packages.save(tourPackage);ra.addFlashAttribute("success","Package saved.");return "redirect:/admin/packages";}
 @PostMapping("/admin/packages/{id}/delete") @PreAuthorize("hasRole('ADMIN')") public String deletePackage(@PathVariable Long id,RedirectAttributes ra){packages.deleteById(id);ra.addFlashAttribute("success","Package deleted.");return "redirect:/admin/packages";}
 @GetMapping("/admin/hotels") @PreAuthorize("hasRole('ADMIN')") public String adminHotels(Model m){m.addAttribute("hotels",hotels.findAll());return "admin/hotels";}
 @GetMapping("/admin/hotels/new") @PreAuthorize("hasRole('ADMIN')") public String newHotel(Model m){m.addAttribute("hotel",new Hotel());return "admin/hotel-form";}
 @PostMapping("/admin/hotels/save") @PreAuthorize("hasRole('ADMIN')") public String saveHotel(@Valid @ModelAttribute Hotel hotel,BindingResult result,RedirectAttributes ra){if(result.hasErrors())return "admin/hotel-form";hotels.save(hotel);ra.addFlashAttribute("success","Hotel saved.");return "redirect:/admin/hotels";}
 @PostMapping("/admin/hotels/{id}/delete") @PreAuthorize("hasRole('ADMIN')") public String deleteHotel(@PathVariable Long id,RedirectAttributes ra){hotels.deleteById(id);ra.addFlashAttribute("success","Hotel deleted.");return "redirect:/admin/hotels";}
 public static class RegistrationForm { public String fullName,email,password,confirmPassword; }
}
